insert into ebd.biblia_versiculos (traducao_id, livro_numero, livro, livro_abreviado, capitulo, versiculo, texto)
values
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 24, 9, 'E, voltando do sepulcro, anunciaram todas estas coisas aos onze, e a todos os outros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 24, 10, 'E eram Maria Madalena, e Joana, e Maria [mãe] de Tiago, e as outras [que estavam] com elas, que diziam estas coisas aos apóstolos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 24, 11, 'E para eles, as palavras delas pareciam não ter sentido; e não creram nelas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 24, 12, 'Porém Pedro, levantando-se, correu ao sepulcro; e abaixando-se, viu os tecidos postos separadamente; e saiu maravilhado com o que tinha acontecido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 24, 13, 'E eis que dois deles iam naquele mesmo dia a uma aldeia, cujo nome era Emaús, que estava a sessenta estádios [de distância] de Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 24, 14, 'E iam falando entre si de todas aquelas coisas que tinham acontecido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 24, 15, 'E aconteceu que, enquanto eles estavam conversando entre si, e perguntando um ao outro, Jesus se aproximou, e foi junto deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 24, 16, 'Mas seus olhos foram retidos, para que não o reconhecessem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 24, 17, 'E disse-lhes: Que conversas são essas, que vós discutis enquanto andam, e ficais tristes?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 24, 18, 'E um [deles] ,cujo nome era Cleofas, respondendo-o, disse-lhe: És tu o único viajante em Jerusalém que não sabe as coisas que nela tem acontecido nestes dias?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 24, 19, 'E ele lhes disse: Quais?E eles lhe disseram: As sobre Jesus de Nazaré, a qual foi um homem profeta, poderoso em obras e em palavras, diante de Deus, e de todo o povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 24, 20, 'E como os chefes dos sacerdotes, e nossos líderes o entregaram à condenação de morte, e o crucificaram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 24, 21, 'E nós esperávamos que ele fosse aquele que libertar a Israel; porém além de tudo isto, hoje é o terceiro dia desde que estas coisas aconteceram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 24, 22, 'Ainda que também algumas mulheres dentre nós nos deixaram surpresos, as quais de madrugada foram ao sepulcro;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 24, 23, 'E não achando seu corpo, vieram, dizendo que também tinham visto uma aparição de anjos, que disseram que ele vive.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 24, 24, 'E alguns do que estão conosco foram ao sepulcro, e [o] acharam assim como as mulheres tinham dito; porém não o viram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 24, 25, 'E ele lhes disse: Ó tolos, e que demoram no coração para crerem em tudo o que os profetas falaram!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 24, 26, 'Por acaso não era necessário que o Cristo sofresse estas coisas, e [então] entrar em sua glória?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 24, 27, 'E começando de Moisés, e por todos os profetas, lhes declarava em todas as Escrituras o que estava [escrito] sobre ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 24, 28, 'E chegaram à aldeia para onde estavam indo; e ele agiu como se fosse para [um lugar] mais distante.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 24, 29, 'E eles lhe rogaram, dizendo: Fica conosco, porque já é tarde, e o dia está entardecendo;E ele entrou para ficar com eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 24, 30, 'E aconteceu que, estando sentado com eles [à mesa] ,tomou o pão, o benzeu, [o] partiu, e o deu a eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 24, 31, 'E os olhos deles se abriram, e o reconheceram, e ele lhes desapareceu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 24, 32, 'E diziam um ao outro: Por acaso não estava nosso coração ardendo em nós, quando ele falava conosco pelo caminho, e quando nos desvendava as Escrituras?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 24, 33, 'E levantando-se na mesma hora, voltaram para Jerusalém, e acharam reunidos aos onze, e aos que estavam com eles,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 24, 34, 'Que diziam: Verdadeiramente o Senhor ressuscitou, e já apareceu a Simão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 24, 35, 'E eles contaram as coisas que [lhes aconteceram] no caminho; e como foi reconhecido por eles quando partiu o pão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 24, 36, 'E enquanto eles falavam disto, o próprio Jesus se pôs no meio deles, e lhes disse: Paz [seja] convosco.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 24, 37, 'E eles, espantados, e muito atemorizados, pensavam que viam algum espírito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 24, 38, 'E ele lhes disse: Por que estais perturbados, e por que sobem dúvidas em vossos corações?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 24, 39, 'Vede minhas mãos, e os meus pés, que sou em mesmo. Tocai-me, e vede, porque um espírito não tem carne nem ossos, como vós vedes que eu tenho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 24, 40, 'E dizendo isto, lhes mostrou as mãos e os pés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 24, 41, 'E eles, não crendo ainda, por causa da alegria, e maravilhados, [Jesus] disse-lhes: Tendes aqui alguma coisa para comer?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 24, 42, 'Então eles lhe apresentaram parte de um peixe assado e de um favo de mel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 24, 43, 'Ele pegou, e comeu diante deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 24, 44, 'E disse-lhes: Estas são as palavras que eu vos disse, enquanto ainda estava convosco, que era necessário que se cumprissem todas as coisas que estão escritas sobre mim na Lei de Moisés, [nos] profetas, e [nos] Salmos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 24, 45, 'Então ele lhes abriu o entendimento, para que entendessem as Escrituras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 24, 46, 'E disse-lhes: Assim está escrito, e assim era necessário que o Cristo sofresse, e que ao terceiro dia ressuscitasse dos mortos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 24, 47, 'E que em seu nome fosse pregado arrependimento e perdão de pecados em todas as nações, começando de Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 24, 48, 'E destas coisas vós sois testemunhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 24, 49, 'E eis que eu envio a promessa de meu Pai sobre vós; porém ficai vós na cidade de Jerusalém, até que vos seja dado poder do alto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 24, 50, 'E os levou para fora até Betânia, e levantando suas mãos, os abençoou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 24, 51, 'E aconteceu que, enquanto os abençoava, ele se afastou deles, e foi conduzido para cima ao céu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 24, 52, 'E eles, adorando-o, voltaram para Jerusalém com grande alegria;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 24, 53, 'E estavam sempre no Templo, louvando e bendizendo a Deus. Amém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 1, 1, 'No princípio era a Palavra, e a Palavra estava junto de Deus, e a Palavra era Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 1, 2, 'Esta estava no princípio junto de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 1, 3, 'Por esta foram feitas todas as coisas, e sem ela não se fez coisa nenhuma do que foi feito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 1, 4, 'Nela estava a vida, e a vida era a luz dos seres humanos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 1, 5, 'E a luz brilha nas trevas; e as trevas não a compreenderam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 1, 6, 'Houve um homem enviado por Deus, cujo nome era João.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 1, 7, 'Este veio por testemunho, para que testemunhasse da Luz, para que todos por ele cressem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 1, 8, 'Ele não era a Luz; mas [foi enviado] para que testemunhasse da Luz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 1, 9, '[Esta] era a luz verdadeira, que ilumina a todo ser humano que vem ao mundo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 1, 10, 'No mundo estava, e por ele foi feito o mundo; e o mundo não o conheceu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 1, 11, 'Ao [seu] próprio veio, e os seus não o receberam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 1, 12, 'Mas a todos quantos o receberam, deu-lhes poder de serem feitos filhos de Deus: aos que creem em seu nome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 1, 13, 'Os quais não são gerados de sangue, nem de vontade da carne, nem de vontade de homem, mas sim de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 1, 14, 'E aquela Palavra se fez carne, e habitou entre nós; (e vimos sua glória, como glória do unigênito do Pai) cheio de graça e de verdade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 1, 15, 'E João dele testemunhou, e clamou, dizendo: Este era aquele, de quem eu dizia: O que vem após mim é antes de mim; porque era primeiro que eu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 1, 16, 'E de sua plenitude recebemos todos também graça por graça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 1, 17, 'Porque a Lei foi dada por Moisés; a graça e a verdade foi feita por Jesus Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 1, 18, 'A Deus nunca ninguém o viu; o unigênito Filho, que está no seio do Pai, ele [o] declarou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 1, 19, 'E este é o testemunho de João, quando os judeus mandaram alguns sacerdotes e levitas de Jerusalém, que lhe perguntassem: Tu quem és?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 1, 20, 'E confessou, e não negou; e confessou: Eu não sou o Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 1, 21, 'E lhe perguntaram: Que, então? És tu Elias? E ele disse: Não sou. [Eles disseram] : Tu és o Profeta? E ele respondeu: Não.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 1, 22, 'Disseram-lhe pois: Quem és? Para darmos resposta aos que nos enviaram. Que dizes de ti mesmo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 1, 23, 'Disse: Eu sou a voz do que clama no deserto: Endireitai o caminho do Senhor, como disse o profeta Isaías.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 1, 24, 'E os enviados eram dos fariseus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 1, 25, 'E perguntaram-lhe, e disseram-lhe: Por que pois batizas, se tu não és o Cristo, nem Elias, nem o profeta?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 1, 26, 'João lhes respondeu, dizendo: Eu batizo com água; mas em meio de vós, está a quem vós não conheceis,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 1, 27, 'Este é aquele que vem após mim, o qual já foi antes de mim, do qual eu não sou digno de desatar a tira de sua sandália.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 1, 28, 'Estas coisas aconteceram em Betábara, do outro lado do Jordão, onde João estava batizando.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 1, 29, 'O dia seguinte viu João a Jesus vir a ele, e disse: Eis o Cordeiro de Deus, que tira o pecado do mundo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 1, 30, 'Este é aquele do qual eu disse: Após mim vem um homem que já foi antes de mim; porque já era primeiro que eu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 1, 31, 'E eu não o conhecia; mas para que fosse manifesto a Israel, por isso vim eu batizando com água.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 1, 32, 'E João testemunhou, dizendo: Eu vi o Espírito como pomba descer do céu, e repousou sobre ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 1, 33, 'E eu não o conhecia, mas aquele que me mandou a batizar com água, esse me disse: Sobre aquele que vires descer ao Espírito, e repousar sobre ele, esse é o que batiza com Espírito Santo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 1, 34, 'E eu [o] vi, e testemunhado tenho, que este é o Filho de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 1, 35, 'O seguinte dia estava outra vez [ali] João, e dois de seus discípulos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 1, 36, 'E vendo [por ali] andar a Jesus, disse: Eis o Cordeiro de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 1, 37, 'E os dois discípulos ouviram[-lhe] dizer [aquilo] , e seguiram a Jesus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 1, 38, 'E Jesus, virando-se, e vendo-os seguir, disse-lhes: Que buscais? E eles lhe disseram: Rabi, (que traduzido, quer dizer, Mestre) onde moras?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 1, 39, 'Disse-lhes ele: Vinde, e vede-o; Vieram, e viram onde morava, e na companhia dele naquele dia; e já era quase a hora décima.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 1, 40, 'Era André, o irmão de Simão Pedro, um dos dois que ouvira aquilo de João, e o haviam seguido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 1, 41, 'Este achou primeiro a seu irmão Simão, e disse-lhe: Já achamos ao Messias(que traduzido, é o Cristo).'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 1, 42, 'E levou-o a Jesus. E Jesus, olhando para ele, disse: Tu és Simão, filho de Jonas; tu serás chamado Cefas. (que se traduz Pedro).'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 1, 43, 'O dia seguinte Jesus quis ir à Galileia, achou Filipe, e disse-lhe: Segue-me.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 1, 44, 'E Filipe era de Betsaida, da cidade de André e de Pedro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 1, 45, 'Filipe achou Natanael, e disse-lhe: Achamos [aquele] de quem Moisés escreveu na Lei, e os Profetas: a Jesus, o filho de José, de Nazaré.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 1, 46, 'E disse-lhe Natanael: Pode haver alguma coisa boa de Nazaré? Filipe lhe disse: Vem, e vê.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 1, 47, 'Jesus viu Natanael vir, e disse dele: Eis verdadeiramente um israelita, em quem não há engano!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 1, 48, 'Natanael lhe disse: De onde tu me conheces? Respondeu Jesus, e disse-lhe: Antes que Filipe te chamasse, estando tu debaixo da figueira, eu te vi.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 1, 49, 'Natanael respondeu, e disse-lhe: Rabi, tu és o Filho de Deus, tu és o Rei de Israel!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 1, 50, 'Jesus respondeu, e disse-lhe: Porque te disse: Debaixo da figueira te vi, crês? Tu verás coisas maiores que estas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 1, 51, 'E disse-lhe: Em verdade, em verdade vos digo, que daqui em diante vereis o céu aberto, e aos anjos de Deus subir e descer sobre o Filho do homem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 2, 1, 'E no terceiro dia houve um casamento em Caná da Galileia; e a mãe de Jesus estava ali.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 2, 2, 'E também Jesus foi convidado com seus discípulos ao casamento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 2, 3, 'E tendo faltado vinho, a mãe de Jesus lhe disse: Não têm vinho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 2, 4, 'Jesus lhe disse: O que eu tenho contigo, mulher? A minha hora ainda não chegou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 2, 5, 'Sua mãe disse aos serventes: Fazei tudo quanto ele vos disser.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 2, 6, 'E estavam ali postos seis vasos de pedra, conforme à purificação dos judeus, em cada uma cabiam duas ou três metretas. )'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 2, 7, 'Disse-lhes Jesus: Enchei estes vasos com água. E encheram-nas até encima.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 2, 8, 'E disse-lhes: Agora tirai, e a levai ao mestre de cerimônia. Então levaram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 2, 9, 'E quando o mestre de cerimônia experimentou a água feita vinho (sem saber de onde era, porém os serventes que haviam tirado a água sabiam), o mestre de cerimônia chamou o noivo,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 2, 10, 'E disse-lhe: Todos põem primeiro o vinho bom, e quando [os convidados] já [estão] bêbados, então [se dá] o pior; [porém] tu guardaste o bom vinho até agora.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 2, 11, 'Este princípio de sinais Jesus fez em Caná da Galileia, e manifestou sua glória; e seus discípulos creram nele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 2, 12, 'Depois disto desceu a Cafarnaum, ele e sua mãe, seus irmãos, e seus discípulos, e ficaram ali não muitos dias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 2, 13, 'E estava perto a Páscoa dos judeus, e Jesus subiu a Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 2, 14, 'E achou no Templo os que vendiam bois, ovelhas, e pombas, e os cambistas sentados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 2, 15, 'E tendo feito um açoite com cordas, lançou todos para fora do Templo, assim como as ovelhas, e os bois; e espalhou o dinheiro dos cambistas, e virou as mesas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 2, 16, 'E aos que vendiam pombas, disse: Tirai isto daqui; e não torneis a casa de meu Pai uma casa de comércio!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 2, 17, 'E lembraram-se seus discípulos que está escrito: O zelo de tua casa me tem me devorado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 2, 18, 'Responderam pois os Judeus, e disseram-lhe: Que sinal nos mostras de que fazes estas coisas?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 2, 19, 'Respondeu Jesus, e disse-lhes: Derrubai este Templo, e em três dias o levantarei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 2, 20, 'Os judeus, pois, disseram: [Durante] quarenta e seis anos este Templo foi edificado, e tu o levantarás tu em três dias?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 2, 21, 'Porém ele falava do Templo de seu corpo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 2, 22, 'Portanto, quando ressuscitou dos mortos, seus discípulos se lembraram que ele lhes tinha dito isto; e creram na Escritura, e na palavra que Jesus tinha [lhes] dito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 2, 23, 'E estando ele em Jerusalém pela páscoa, na festa, muitos creram em seu nome, ao verem os sinais que ele fazia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 2, 24, 'Mas o mesmo Jesus a si mesmo não confiava neles, porque conhecia a todos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 2, 25, 'E não necessitava de que alguém [lhe] desse testemunho de ser humano algum, pois ele bem sabia o que havia no [interior do] ser humano.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 3, 1, 'E havia um homem dos fariseus, cujo nome era Nicodemos, chefe dos judeus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 3, 2, 'Este veio a Jesus de noite, e disse-lhe: Rabi, bem sabemos que és Mestre vindo de Deus; porque ninguém pode fazer estes sinais que tu fazes, se Deus não for com ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 3, 3, 'Respondeu Jesus e disse-lhe: Em verdade, em verdade te digo, que aquele que não voltar a nascer, não pode ver o Reino de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 3, 4, 'Nicodemos lhe disse: Como pode o homem nascer, sendo [já] velho? Pode ele voltar a entrar no ventre de sua mãe, e nascer?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 3, 5, 'Respondeu Jesus: Em verdade, em verdade te digo, que aquele que não nascer de água e [do] Espírito, não pode entrar no Reino de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 3, 6, 'O que é nascido de carne, carne é; e o que é nascido do Espírito, espírito é.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 3, 7, 'Não te maravilhes de que te disse: necessário vos é voltar a nascer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 3, 8, 'O vento sopra onde quer, e ouves o seu som; porém não sabes de onde vem, nem para onde vai; assim é todo aquele que é nascido do Espírito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 3, 9, 'Nicodemos respondeu, e disse-lhe: Como pode isto acontecer?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 3, 10, 'Jesus respondeu, e disse-lhe: Tu és mestre de Israel, e isto não sabes?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 3, 11, 'Em verdade, em verdade te digo, que o que sabemos, falamos; e o que temos visto, testemunhamos; e não aceitais nosso testemunho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 3, 12, 'Se eu vos disse coisas terrenas, e não credes, como crereis, se vos disser as celestiais?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 3, 13, 'E ninguém subiu ao céu, a não ser o que desceu do céu: o Filho do homem, que está no céu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 3, 14, 'E como Moisés levantou a serpente no deserto, assim deve o Filho do homem ser levantado,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 3, 15, 'Para que todo aquele que nele crer não pereça, mas tenha a vida eterna.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 3, 16, 'Porque Deus amou ao mundo de tal maneira, que deu o seu Filho unigênito; para que todo aquele que nele crê não pereça, mas tenha a vida eterna.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 3, 17, 'Porque Deus não mandou seu Filho ao mundo para que condenasse ao mundo; mas sim para que o mundo por ele fosse salvo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 3, 18, 'Quem nele crer não é condenado; mas quem não crê já está condenado; pois não tem crido no nome do unigênito Filho de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 3, 19, 'E esta é a condenação: que a luz veio ao mundo, e as pessoas amaram mais as trevas que a luz, porque suas obras eram más.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 3, 20, 'Porque todo aquele que faz o mal odeia a luz e não vem à luz, para que suas obras não sejam reprovadas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 3, 21, 'Mas quem pratica a verdade vem à luz, para que suas obras sejam manifestas, que são feitas em Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 3, 22, 'Depois disto Jesus veio com seus discípulos à terra da Judeia; e estava ali com eles, e batizava.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 3, 23, 'E João também batizava em Enom, junto a Salim, porque havia ali muitas águas; e vinham [ali] , e eram batizados,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 3, 24, 'Porque João ainda não tinha sido lançado na prisão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 3, 25, 'Houve pois uma discussão dos Discípulos de João com os judeus sobre a purificação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 3, 26, 'E vieram a João, e disseram-lhe: Rabi, aquele que estava contigo dalém do Jordão, ao qual tu deste testemunho, eis que batiza, e todos vem a ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 3, 27, 'João respondeu, e disse: O ser humano não pode receber coisa alguma, se não lhe for dada do céu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 3, 28, 'Vós mesmos me sois testemunhas, que disse: Eu não sou o Cristo; mas que sou enviado diante dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 3, 29, 'Aquele que tem a esposa, é o esposo; mas o amigo do esposo, que [o] apoia, e lhe ouve, alegra-se muito pela voz do esposo. Assim pois já este meu gozo é cumprido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 3, 30, 'A ele convém crescer, porém a mim diminuir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 3, 31, 'Aquele que vem de cima, é sobre todos; aquele que [vem] da terra, da terra é, e da terra fala. Aquele que vem do céu é sobre todos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 3, 32, 'E daquilo que viu e ouviu, isto testemunha; e ninguém aceita seu testemunho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 3, 33, 'Aquele que aceitou seu testemunho, esse selou que Deus é verdadeiro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 3, 34, 'Porque aquele que Deus enviou, as palavras de Deus fala; porque não [lhe] dá Deus o Espírito por medida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 3, 35, 'O Pai ama ao Filho, e todas as coisas [lhe] deu em sua mão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 3, 36, 'Aquele que crê no Filho tem vida eterna; porém aquele que é desobediente ao Filho não verá a vida [eterna] , mas a ira de Deus continua sobre ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 4, 1, 'Quando, pois, o Senhor entendeu que os fariseus ouviram que Jesus fazia e batizava mais discípulos que João'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 4, 2, '(ainda que Jesus mesmo não batizava, mas sim seus discípulos),'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 4, 3, 'Ele deixou a Judeia, e foi outra vez para a Galileia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 4, 4, 'E foi necessário passar por Samaria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 4, 5, 'Veio pois a uma cidade de Samaria, chamada Sicar, junto à propriedade que Jacó deu a seu filho José.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 4, 6, 'E ali estava a fonte de Jacó. Então Jesus, cansado do caminho, sentou-se assim junto à fonte; era isto quase à hora sexta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 4, 7, 'Veio uma mulher de Samaria para tirar água; Disse-lhe Jesus: Dá-me de beber.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 4, 8, '(Porque seus discípulos haviam ido à cidade para a comprar de comer).'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 4, 9, 'Disse-lhe pois a mulher samaritana: Como, sendo tu judeu, me pedes de beber, que sou mulher samaritana? (Porque os judeus não se comunicam com o samaritanos.)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 4, 10, 'Respondeu Jesus, e disse-lhe: Se tu conhecesses o dom de Deus, e quem é o que te diz: Dá-me de beber, tu lhe pedirias, e ele te daria água viva.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 4, 11, 'Disse a mulher: Senhor, tu não tens com que [a] tirar, e o poço é fundo; de onde pois tens a água viva?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 4, 12, 'És tu maior que nosso pai Jacó, que nos deu o poço? E ele mesmo dele bebeu, e seus filhos, e seu gado?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 4, 13, 'Jesus respondeu, e disse-lhe: Todo aquele que beber desta água voltará a ter sede;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 4, 14, 'Porém aquele que beber da água que eu lhe der, para sempre não terá sede, mas a água que eu lhe der se fará nele fonte de água, que salte para vida eterna.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 4, 15, 'Disse-lhe a mulher: Senhor, dá-me desta água, para que eu não tenha [mais] sede, nem venha aqui para tirar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 4, 16, 'Disse-lhe Jesus: Vai, chama a teu marido, e vem cá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 4, 17, 'A mulher respondeu, e disse: Não tenho marido. Disse-lhe Jesus: Bem disseste: Marido não tenho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 4, 18, 'Porque cinco maridos tiveste, e o que agora tens não é teu marido; isto com verdade disseste.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 4, 19, 'Disse-lhe a mulher: Senhor, vejo que és profeta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 4, 20, 'Nossos pais adoraram neste monte, e vós dizeis que em Jerusalém é o lugar onde se deve adorar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 4, 21, 'Disse-lhe Jesus: Mulher, crê em mim, que a hora vem, quando nem neste monte, nem em Jerusalém, adorareis ao Pai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 4, 22, 'Vós adorais o que não sabeis; nós adoramos o que sabemos, porque a salvação vem dos judeus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 4, 23, 'Porém a hora vem, e agora é, quando os verdadeiros adoradores adorarão ao Pai em espírito e em verdade; porque também o Pai busca a tais que o adorem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 4, 24, 'Deus é Espírito, e os que o adoram devem adorá [-lo] em espírito e em verdade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 4, 25, 'Disse-lhe a mulher: Eu sei que o Messias vem (que se chama o Cristo); quando ele vier, todas as coisas nos anunciará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 4, 26, 'Disse-lhe Jesus: Eu sou o que contigo falo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 4, 27, 'E nisto vieram seus discípulos; e maravilharam-se de que falasse com uma mulher; mas ninguém [lhe] disse: Que perguntas? ou, O que falas com ela?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 4, 28, 'Deixou, pois, a mulher seu vaso de água, e foi à cidade, e disse ao povo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 4, 29, 'Vinde, vede um homem que me disse tudo quanto tenho feito; por acaso não é este o Cristo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 4, 30, 'Saíram, pois, da cidade, e vieram a ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 4, 31, 'E enquanto isso, os discípulos lhe pediam, dizendo: Rabi, come.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 4, 32, 'Porém ele lhes disse: Uma comida tenho que comer, que vós não sabeis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 4, 33, 'Diziam, pois, os discípulos uns aos outros: Por acaso alguém lhe trouxe de comer?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 4, 34, 'Disse-lhes Jesus: Minha comida é fazer a vontade daquele que me enviou, e cumprir sua obra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 4, 35, 'Não dizeis vós, que ainda há quatro meses até que venha a ceifa? Eis que vos digo: Levantai vossos olhos, e vede as terras; porque já estão brancas para a ceifa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 4, 36, 'E o que ceifa, recebe recompensa, e junta fruto para vida eterna; para que ambos se alegrem, tanto o que semeia, quanto o que ceifa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 4, 37, 'Porque nisto é verdadeiro o ditado, que: Um é o que semeia, e outro o que ceifa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 4, 38, 'Eu vos enviei para ceifar onde vós não trabalhastes; outros trabalharam, e vós entrastes no trabalho deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 4, 39, 'E muitos dos samaritanos daquela cidade creram nele pela palavra da mulher, que testemunhava, dizendo: Ele me disse tudo quanto eu tenho feito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 4, 40, 'Vindo pois os samaritanos a ele, suplicaram-lhe que ficasse com eles; e ele ficou ali dois dias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 4, 41, 'E creram ainda muitos mais pela palavra dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 4, 42, 'E diziam à mulher: Já não cremos por teu dito; porque nós mesmos temos [o] ouvido, e sabemos que verdadeiramente este é o Cristo, o Salvador do mundo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 4, 43, 'E depois de dois dias partiu dali, e foi-se para a Galileia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 4, 44, 'Porque o mesmo Jesus testemunhou que não tem o Profeta honra em sua própria terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 4, 45, 'Vindo pois para a Galileia, os Galileus o receberam, havendo visto todas as coisas que fizera em Jerusalém no [dia] da festa, porque também eles foram ao [dia] da festa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 4, 46, 'Veio pois Jesus outra vez a Caná da Galileia, onde da água fizera vinho. E estava ali um nobre, cujo filho estava enfermo em Cafarnaum.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 4, 47, 'Ouvindo este que Jesus vinha da Judeia para a Galileia, foi ter com ele, e suplicava-lhe que descesse, e curasse a seu filho, porque já estava à morte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 4, 48, 'Disse-lhe pois Jesus: Se não virdes sinais e milagres não crereis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 4, 49, 'O nobre lhe disse: Senhor, desce, antes que meu filho morra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 4, 50, 'Disse-lhe Jesus: Vai, teu filho vive. E o homem creu na palavra que Jesus lhe disse, e se foi.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 4, 51, 'E [estando] ele já descendo, seus servos lhe saíram ao encontro, e [lhe] anunciaram, dizendo: Teu filho vive.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 4, 52, 'Perguntou-lhes pois, a que hora se achara melhor; e disseram-lhe: Ontem às sete horas a febre o deixou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 4, 53, 'Entendeu pois o pai, que aquela era a mesma hora em que Jesus lhe disse: Teu filho vive. E creu nele, e toda sua casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 4, 54, 'Este segundo sinal Jesus voltou a fazer, quando ele veio d [a] Judeia a Galileia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 5, 1, 'Depois disto houve uma festa dos judeus, e subiu Jesus para Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 5, 2, 'E há em Jerusalém à [porta] das ovelhas um tanque, que em hebraico se chama Betesda, que tem cinco entradas cobertas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 5, 3, 'Nestes jazia grande multidão de enfermos, cegos, mancos, [e de corpo] ressecado, aguardando o movimento da água.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 5, 4, 'Porque um anjo descia de vez em quando ao tanque, e agitava a água; e o primeiro que descia nele, depois do movimento da água, sarava de qualquer enfermidade que tivesse.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 5, 5, 'E estava ali um certo homem, que havia trinta e oito anos que estava enfermo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 5, 6, 'Vendo Jesus a este deitado, e sabendo, que já havia muito tempo que [ali] jazia, disse-lhe: Queres sarar?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 5, 7, 'Respondeu-lhe o enfermo: Senhor, não tenho homem algum para que, quando a água se agita, me ponha no tanque; e enquanto eu venho, outro desce antes de mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 5, 8, 'Disse-lhe Jesus: Levanta-te, toma teu leito, e anda.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 5, 9, 'E logo aquele homem sarou; e tomou seu leito, e andou. E era Sábado aquele dia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 5, 10, 'Disseram pois os judeus para aquele que fora curado: É Sábado, não te é lícito levar o leito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 5, 11, 'Respondeu-lhes ele: Aquele que me curou, esse me disse: Toma teu leito, e anda.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 5, 12, 'Perguntaram-lhe pois: Quem é o homem que te disse: Toma teu leito e anda?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 5, 13, 'E o que fora curado, não sabia quem [o] era, porque Jesus se havia retirado, porque naquele lugar havia uma [grande] multidão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 5, 14, 'Depois Jesus achou-o no Templo, e disse-lhe: Eis que já estás são; não peques mais, para que não te suceda alguma coisa pior.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 5, 15, 'Aquele homem foi anunciar aos judeus que Jesus era o que o curara.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 5, 16, 'E por isso os judeus perseguiam Jesus e procuravam matá-lo, porque ele fazia estas coisas no sábado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 5, 17, 'E Jesus lhes respondeu: Meu Pai até agora trabalha, e eu [também] trabalho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 5, 18, 'Por isto ainda mais procuravam os Judeus matá-lo, porque não só quebrava o sábado, mas também dizia que Deus era seu próprio Pai, fazendo-se igual a Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 5, 19, 'Respondeu pois Jesus, e disse-lhes: Em verdade, em verdade vos digo, que não pode o Filho fazer coisa alguma de si mesmo, a não ser aquilo que ele veja o Pai fazer; porque todas as coisas que ele faz, semelhantemente o Filho também as faz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 5, 20, 'Porque o Pai ama ao Filho, e todas as coisas que faz lhe mostra; e maiores obras que estas lhe mostrará, para que vós vos maravilheis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 5, 21, 'Porque como o Pai aos mortos ressuscita e vivifica, assim também o Filho aos que quer vivifica.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 5, 22, 'Porque também o Pai a ninguém julga, mas todo o juízo deu ao Filho,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 5, 23, 'Para que todos honrem ao Filho, como honram ao Pai. Quem não honra ao Filho, não honra ao Pai que o enviou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 5, 24, 'Em verdade, em verdade vos digo, que quem ouve minha palavra, e crê ao que me enviou, tem vida eterna, e não virá em condenação, mas passou da morte para a vida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 5, 25, 'Em verdade, em verdade vos digo, que a hora vem, e agora é, quando os mortos ouvirão a voz do Filho de Deus, e aos que ao ouvirem, viverão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 5, 26, 'Porque como o Pai tem vida em si mesmo, assim deu também ao Filho que tivesse vida em si mesmo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 5, 27, 'E deu-lhe poder, para fazer juízo, porque é o Filho do homem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 5, 28, 'Não vos maravilheis disto; porque a hora vem, em que todos os que estão nos sepulcros ouvirão sua voz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 5, 29, 'E sairão os que fizeram bem, para a ressurreição de vida; e os que fizeram mal, à ressurreição de condenação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 5, 30, 'Não posso eu de mim mesmo fazer alguma coisa. Como ouço, [assim] julgo; e meu juízo é justo; porque não busco minha vontade, mas a vontade do Pai que me enviou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 5, 31, 'Se eu testemunho de mim mesmo, meu testemunho não é verdadeiro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 5, 32, 'Outro há que testemunha de mim, e sei que o testemunho, que testemunha de mim, é verdadeiro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 5, 33, 'Vós enviastes [mensageiros] a João, e ele deu testemunho à verdade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 5, 34, 'Porém eu não recebo testemunho humano; mas digo isto para que sejais salvos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 5, 35, 'Ele era uma lâmpada ardente e brilhante; e vós quisestes por um pouco de tempo alegrar em sua luz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 5, 36, 'Mas eu tenho maior testemunho que [o] de João; porque as obras que o Pai me deu que cumprisse, as mesmas obras que eu faço, testemunham de mim que o Pai me enviou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 5, 37, 'E o Pai que me enviou, ele mesmo testemunhou de mim. Nunca ouvistes sua voz, nem vistes sua aparência.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 5, 38, 'E não tendes sua palavra permanecendo em vós; porque ao que ele enviou, a esse vós não credes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 5, 39, 'Investigai as Escrituras; porque vós pensais que nelas tendes a vida eterna, e elas são as que de mim testemunham.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 5, 40, 'E não quereis vir a mim, para que tenhais vida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 5, 41, 'Não recebo honra humana.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 5, 42, 'Mas eu bem vos conheço que não tendes o amor de Deus em vós mesmos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 5, 43, 'Eu vim em nome de meu Pai, e vós não me aceitais; se outro vier em seu próprio nome, a esse aceitareis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 5, 44, 'Como podeis vós crer, [se] tomais honra uns dos outros, e não buscais a honra que [vem] somente de Deus?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 5, 45, 'Não penseis que eu vos tenha de acusar para com o Pai; o que vos acusa é Moisés, em quem vós esperais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 5, 46, 'Porque se vós crêsseis em Moisés, [também] a mim me creríeis; porque de mim ele escreveu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 5, 47, 'Mas se não credes em seus escritos, como crereis em minhas palavras?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 6, 1, 'Depois disto Jesus partiu para a outro lado do mar da Galileia, que é o de Tibérias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 6, 2, 'E uma grande multidão o seguia, porque viam seus sinais que ele fazia nos enfermos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 6, 3, 'E subiu Jesus ao monte, e sentou-se ali com seus discípulos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 6, 4, 'E já a Páscoa, a festa dos judeus, estava perto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 6, 5, 'Levantando pois Jesus os olhos, e vendo que uma grande multidão vinha a ele, disse a Filipe: De onde comparemos pães, para que estes comam?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 6, 6, '(Mas ele disse isto para o testar; pois ele bem sabia o que havia de fazer.)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 6, 7, 'Respondeu-lhe Filipe: Duzentos dinheiros de pão não lhes bastarão, para que cada um deles tome um pouco.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 6, 8, 'Disse-lhe um de seus discípulos, André, o irmão de Simão Pedro:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 6, 9, 'Um menino está aqui que tem cinco pães de cevada e dois peixinhos; mas que é isto entre tantos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 6, 10, 'E disse Jesus: Fazei sentar as pessoas; e havia muita erva naquele lugar. Sentaram-se, pois, os homens, em número de cinco mil.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 6, 11, 'E tomou Jesus os pães, e havendo dado graças, repartiu-os aos discípulos, e os discípulos aos que estavam sentados, semelhantemente também dos peixes, quanto queriam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 6, 12, 'E quando já estiveram fartos, disse ele a seus discípulos: Recolhei os pedaços que sobraram, para que nada se perca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 6, 13, 'Então eles os recolheram, e encheram doze cestos de pedaços dos cinco pães de cevada, que sobraram aos que tinham comido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 6, 14, 'Vendo, pois, aquelas pessoas o sinal que Jesus fizera, disseram: Este é verdadeiramente o Profeta que havia de vir ao mundo!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 6, 15, 'Sabendo pois Jesus que viriam, e o tomariam, para fazê-lo rei, voltou a se retirar sozinho ao monte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 6, 16, 'E quando veio o entardecer, seus discípulos desceram para o mar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 6, 17, 'E entrando no barco, vieram do outro lado do mar para Cafarnaum. E era já escuro, e Jesus [ainda] não tinha vindo a eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 6, 18, 'E o mar se levantou, porque um grande vento soprava.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 6, 19, 'E havendo já navegado quase vinte e cinco, ou trinta estádios, viram a Jesus andando sobre o mar, e se aproximando do barco; e temeram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 6, 20, 'Mas ele lhes disse: Sou eu, não temais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 6, 21, 'Eles, então, o receberam com agrado no barco; e logo o barco chegou à terra para onde iam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 6, 22, 'O dia seguinte, vendo a multidão, que estava do outro lado do mar, que não havia ali mais que um barquinho, em que seus discípulos entraram; e que Jesus não entrara com seus discípulos naquele barquinho, mas [que] seus discípulos sós se haviam ido;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 6, 23, '(Porém outros barquinhos vieram de Tibérias, perto do lugar onde comeram o pão, havendo o Senhor dado graças.)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 6, 24, 'Vendo pois a multidão que Jesus não estava ali, nem seus discípulos, entraram eles também nos barcos, e vieram a Cafarnaum em busca de Jesus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 6, 25, 'E achando-o do outro lado do mar, disseram: Rabi, quando chegaste aqui?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 6, 26, 'Respondeu-lhes Jesus, e disse: Em verdade, em verdade vos digo, que me buscais, não pelos sinais que vistes, mas pelo pão que comestes, e vos fartastes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 6, 27, 'Trabalhai não [pela] comida que perece, mas sim [pela] comida que permanece para vida eterna, a qual o Filho do homem vos dará; porque Deus Pai a este selou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 6, 28, 'Disseram-lhe pois: Que faremos para trabalhar as obras de Deus?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 6, 29, 'Respondeu Jesus, e disse-lhes: Esta é a obra de Deus: que creiais naquele que ele enviou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 6, 30, 'Disseram-lhe pois: Que sinal, pois, fazes tu para que o vejamos, e em ti creiamos? O que tu operas?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 6, 31, 'Nossos pais comeram o maná no deserto, como está escrito: Pão do céu ele lhes deu para comer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 6, 32, 'Então Jesus lhes disse: Em verdade, em verdade vos digo, que Moisés não vos deu o pão do céu; mas meu Pai vos dá o verdadeiro pão do céu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 6, 33, 'Porque o pão de Deus é aquele que desce do céu e dá vida ao mundo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 6, 34, 'Disseram-lhe pois: Senhor, dá-nos sempre [d] este pão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 6, 35, 'E Jesus lhes disse: Eu sou o pão da vida; quem vem a mim de maneira nenhuma terá fome, e quem crê em mim nunca terá sede.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 6, 36, 'Mas já tenho vos dito que também me vistes, e não credes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 6, 37, 'Tudo o que o Pai me dá virá a mim; e ao que vem a mim, em maneira nenhuma o lançarei fora.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 6, 38, 'Porque eu desci do céu, não para fazer minha vontade, mas sim a vontade daquele que me enviou;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 6, 39, 'E esta é a vontade do Pai, que me enviou: que de tudo quanto me deu, nada perca, mas que eu o ressuscite no último dia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 6, 40, 'E esta é a vontade daquele que me enviou, que todo aquele que vê ao Filho, e nele crê, tenha a vida eterna; e eu o ressuscitarei no último dia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 6, 41, 'Então os judeus murmuravam dele, porque ele tinha dito: Eu sou o pão que desceu do céu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 6, 42, 'E diziam: Não é este Jesus o filho de José, cujos pai e mãe nós conhecemos? Como, pois, ele diz: Desci do céu?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 6, 43, 'Respondeu, então, Jesus, e disse-lhes: Não murmureis entre vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 6, 44, 'Ninguém pode vir a mim se o Pai que me enviou não o trouxer; e eu o ressuscitarei no último dia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 6, 45, 'Escrito está nos profetas: E todos serão ensinados por Deus. Portanto todo aquele que do Pai ouviu e aprendeu, esse vem a mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 6, 46, 'Não que alguém tenha visto ao Pai, a não ser aquele que é de Deus; este tem visto ao Pai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 6, 47, 'Em verdade, em verdade vos digo, que aquele que crê em mim tem vida eterna.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 6, 48, 'Eu sou o pão da vida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 6, 49, 'Vossos pais comeram o maná no deserto, e morreram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 6, 50, 'Este é o pão que desceu do céu, para que o ser humano coma dele e não morra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 6, 51, 'Eu sou o pão vivo, que desceu do céu; se alguém comer deste pão, para sempre viverá. E o pão que eu darei é minha carne, a qual darei pela vida do mundo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 6, 52, 'Discutiam, pois, os Judeus entre si, dizendo: Como este pode nos dar [sua] carne para comer?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 6, 53, 'Jesus, então, lhes disse: Em verdade, em verdade vos digo, que se não comerdes a carne do Filho do homem e beberdes seu sangue, não tereis vida em vós mesmos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 6, 54, 'Quem come minha carne e bebe meu sangue tem vida eterna, e eu o ressuscitarei no último dia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 6, 55, 'Porque minha carne verdadeiramente é comida; e meu sangue verdadeiramente é bebida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 6, 56, 'Quem come minha carne e bebe meu sangue, em mim permanece, e eu nele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 6, 57, 'Como o Pai vivo me enviou, e eu vivo pelo Pai, assim quem come a mim também por mim viverá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 6, 58, 'Este é o pão que desceu do céu. Não como vossos pais, que comeram o maná e morreram; quem comer este pão viverá para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 6, 59, 'Estas coisas ele disse na sinagoga, ensinando em Cafarnaum.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 6, 60, 'Muitos pois de seus discípulos, ao ouvirem [isto] , disseram: Dura é esta palavra; quem a pode ouvir?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 6, 61, 'Sabendo, pois, Jesus em si mesmo, que seus discípulos murmuravam disso, disse-lhes: Isto vos ofende?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 6, 62, '[Que seria] pois, se vísseis ao Filho do homem subir aonde estava primeiro?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 6, 63, 'O Espírito é o que vivifica, a carne para nada aproveita; as palavras que eu vos digo são espírito e são vida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 6, 64, 'Mas há alguns de vós que não creem.Porque Jesus já sabia desde o princípio quem eram os que não criam, e quem era o que o entregaria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 6, 65, 'E dizia: Por isso tenho vos dito que ninguém pode vir a mim, se não lhe for concedido por meu Pai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 6, 66, 'Desde então muitos de seus discípulos voltaram atrás, e já não andavam com ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 6, 67, 'Disse, então, Jesus aos doze: Por acaso também vós quereis ir?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 6, 68, 'Respondeu-lhe pois Simão Pedro: Senhor, a quem iremos? Tu tens as palavras da vida eterna;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 6, 69, 'E nós cremos e conhecemos que tu és o Cristo, o Filho do Deus vivo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 6, 70, 'Jesus lhes respondeu: Por acaso não [fui] eu que vos escolhi, os doze? Porém um de vós é um diabo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 6, 71, 'E ele dizia [isto] de Judas de Simão Iscariotes; porque ele o entregaria, o qual era um dos doze.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 7, 1, 'E depois disto andava Jesus na Galileia; e já não queria andar na Judeia, porque os judeus procuravam matá-lo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 7, 2, 'E já estava perto a festa dos tabernáculos dos judeus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 7, 3, 'Disseram-lhe pois seus irmãos: Parti daqui, e vai-te para a Judeia, para que também teus discípulos vejam as tuas obras que fazes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 7, 4, 'Pois ninguém que procura ser conhecido faz coisa alguma em oculto. Se fazes estas coisas, manifesta-te ao mundo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 7, 5, 'Porque nem mesmo os seus irmãos criam nele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 7, 6, 'Então Jesus lhes disse: Meu tempo ainda não é chegado; mas vosso tempo sempre está pronto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 7, 7, 'O mundo não pode vos odiar, mas a mim me odeia, porque dele testemunho que suas obras são más.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 7, 8, 'Subi vós para esta festa; eu não subo ainda a esta festa, porque ainda meu tempo não é cumprido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 7, 9, 'E havendo-lhes dito isto, ficou na Galileia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 7, 10, 'Mas havendo seus irmãos já subido, então subiu ele também à festa, não abertamente, mas como em oculto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 7, 11, 'Buscavam-no pois os judeus na festa, e diziam: Onde ele está?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 7, 12, 'E havia grande murmuração dele nas multidões. Alguns diziam: Ele é Bom;e outros diziam: Não; ele, porém, engana a multidão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 7, 13, 'Todavia ninguém falava dele abertamente, com medo dos judeus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 7, 14, 'Porém no meio da festa subiu Jesus ao Templo, e ensinava.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 7, 15, 'E maravilhavam-se os Judeus, dizendo: Como este sabe as Escrituras, não as havendo aprendido?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 7, 16, 'Respondeu-lhes Jesus, e disse: Minha doutrina não é minha, mas sim daquele que me enviou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 7, 17, 'Se alguém quiser fazer sua vontade, da doutrina conhecerá, se é de Deus, ou [se] eu falo de mim mesmo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 7, 18, 'Quem fala de si mesmo busca sua própria honra; mas quem busca a honra daquele que o enviou, esse é verdadeiro, e não há nele injustiça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 7, 19, 'Não vos deu Moisés a Lei? Mas ninguém de vós cumpre a Lei. Por que procurais me matar?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 7, 20, 'Respondeu a multidão, e disse: Tens demônio; quem procura te matar?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 7, 21, 'Respondeu Jesus, e disse-lhes: Uma obra fiz, e todos vos maravilhais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 7, 22, 'Por isso Moisés vos deu a circuncisão (não porque seja de Moisés, mas dois pais) e no sábado circuncidais ao homem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 7, 23, 'Se o homem recebe a circuncisão no sábado, para que a Lei de Moisés não seja quebrada, irritai-vos comigo, porque no sábado curei por completo um homem?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 7, 24, 'Não julgueis segundo a aparência, mas julgai juízo justo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 7, 25, 'Diziam, pois, alguns dos de Jerusalém: Não é este ao que procuram matar?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 7, 26, 'E eis que ele fala livremente, e nada lhe dizem; por acaso é verdade que os chefes sabem que este realmente é o Cristo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 7, 27, 'Mas este bem sabemos de onde é: Porém quando vier o Cristo, ninguém saberá de onde é.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 7, 28, 'Exclamava pois Jesus no Templo, ensinando, e dizendo: E a mim me conheceis, e sabeis de onde sou; e eu não vim de mim mesmo; mas aquele que me enviou é verdadeiro, ao qual vós não conheceis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 7, 29, 'Porém eu o conheço, porque dele sou, e ele me enviou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 7, 30, 'Procuravam pois prendê-lo, mas ninguém pôs a mão nele, porque sua hora ainda não era vinda.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 7, 31, 'E muitos da multidão creram nele, e diziam: Quando o Cristo vier, fará ainda mais sinais do que os que este tem feito?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 7, 32, 'Ouviram os fariseus que a multidão murmurava estas coisas sobre ele; e os fariseus e os chefes dos Sacerdotes mandaram oficiais para prendê-lo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 7, 33, 'Disse-lhes pois Jesus: Ainda um pouco de tempo estou convosco, e [então] me irei para aquele que me enviou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 7, 34, 'Vós me buscareis, mas não [me] achareis; e onde eu estou vós não podeis vir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 7, 35, 'Disseram, pois, os judeus uns aos outros: Para onde este se irá, que não o acharemos? Por acaso ele irá aos dispersos entre os gregos, e a ensinar aos gregos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 7, 36, 'Que palavra é esta que disse: Vós me buscareis, mas não [me] achareis; e onde eu estou vós não podeis vir?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 7, 37, 'E no último e grande dia da festa se pôs Jesus em pé, e exclamou, dizendo: Se alguém tem sede, venha a mim, e beba.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 7, 38, 'Quem crê em mim, como diz a Escritura, rios de água viva correrão do interior de seu corpo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 7, 39, '(E ele disse isto do Espírito que receberiam aqueles que nele cressem; pois o Espírito Santo ainda não era [vindo] ,porque Jesus ainda não havia sido glorificado).'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 7, 40, 'Então muitos da multidão, ouvindo esta palavra, diziam: Verdadeiramente este é o Profeta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 7, 41, 'Outros diziam: Este é o Cristo; e outros diziam: Por acaso vem o Cristo da Galileia?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 7, 42, 'Não diz a Escritura que o Cristo virá da semente de Davi, e da aldeia de Belém, de onde era Davi?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 7, 43, 'Por isso havia divisão de opiniões na multidão por causa dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 7, 44, 'E alguns deles queriam prendê-lo, mas ninguém pôs a mão nele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 7, 45, 'Vieram pois os oficiais dos sacerdotes e fariseus; e eles lhes disseram: Por que não o trouxestes?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 7, 46, 'Os oficiais responderam: Ninguém jamais falou assim como este homem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 7, 47, 'Responderam-lhes, pois, os fariseus: Estais vós também enganados?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 7, 48, 'Por acaso algum dos chefes ou dos fariseus creu nele?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 7, 49, 'Mas esta multidão, que não sabe a Lei, maldita é.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 7, 50, 'Disse-lhes Nicodemos, o que viera a ele de noite, que era um deles:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 7, 51, 'Por acaso nossa Lei julga ao homem sem primeiro o ouvir, e entender o que faz?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 7, 52, 'Responderam eles, e disseram: És tu também da Galileia? Pesquisa, e vê que nenhum profeta se levantou da Galileia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 7, 53, 'E cada um foi para sua casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 8, 1, 'Porém Jesus foi para o monte das Oliveiras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 8, 2, 'E pela manhã cedo voltou ao Templo, e todo o povo veio a ele; e sentando-se, ensinava-os.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 8, 3, 'E trouxeram-lhe os escribas e fariseus uma mulher tomada em adultério;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 8, 4, 'E pondo-a no meio, disseram-lhe: Mestre, esta mulher foi tomada no momento em que estava adulterando.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 8, 5, 'E na Lei nos mandou Moisés, que as tais sejam apedrejadas; tu pois que dizes?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 8, 6, 'E isto diziam eles, tentando-o, para que tivessem de que o acusar. Mas inclinando-se Jesus, escrevia com o dedo na terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 8, 7, 'E enquanto continuavam lhe perguntando, ele se endireitou, e disse-lhes: Aquele de vós que está sem pecado, [seja] o primeiro que atire pedra contra ela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 8, 8, 'E voltando a se inclinar, escrevia na terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 8, 9, 'Porém ouvindo eles [isto] , e acusados pela [própria] consciência, saíram um a um, começando dos mais velhos até os últimos; e Jesus ficou só, e a mulher, que estava no meio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 8, 10, 'E endireitando-se Jesus, e não vendo a ninguém além da mulher, disse-lhe: Mulher, onde estão aqueles teus acusadores? Ninguém te condenou?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 8, 11, 'E disse ela: Ninguém, Senhor. E disse-lhe Jesus: Nem eu também te condeno; vai, e não peques mais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 8, 12, 'Falou-lhes pois Jesus outra vez, dizendo: Eu sou a luz do mundo; quem me seguir não andará em trevas, mas terá luz de vida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 8, 13, 'Disseram-lhe pois os Fariseus: Tu testemunhas de ti mesmo; teu testemunho não é verdadeiro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 8, 14, 'Respondeu Jesus, e disse-lhes: Ainda que eu testemunho de mim mesmo, meu testemunho é verdadeiro; porque sei de onde vim, e para onde vou; porém vós não sabeis, de onde venho, nem para onde vou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 8, 15, 'Vós julgais segundo a carne, eu não julgo a ninguém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 8, 16, 'E se eu também julgo, meu juízo é verdadeiro; porque não sou eu só, mas eu, e o Pai que me enviou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 8, 17, 'E também em vossa Lei está escrito que o testemunho de duas pessoas é verdadeiro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 8, 18, 'Eu sou o que testemunho de mim mesmo; e [também] de mim testemunha o Pai, que me enviou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 8, 19, 'Disseram-lhe pois: Onde está teu Pai? Respondeu Jesus: Nem a mim me conheceis, nem a meu Pai; se vós a mim conhecêsseis, também conheceríeis a meu Pai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 8, 20, 'Estas palavras falou Jesus junto à arca do tesouro, ensinando no Templo; e ninguém o prendeu, porque sua hora ainda não era chegada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 8, 21, 'Disse-lhes pois Jesus outra vez: Eu me vou, e me buscareis, e morrereis em vosso pecado; para onde eu vou vós não podeis vir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 8, 22, 'Diziam, pois, os Judeus: Ele, por acaso, matará a si mesmo? Pois diz: Para onde eu vou vós não podeis vir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 8, 23, 'E ele lhes dizia: Vós sois de baixo, eu sou de cima; vós sois deste mundo, eu não sou deste mundo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 8, 24, 'Por isso eu vos disse, que morrereis em vossos pecados; porque se não credes que eu sou, morrereis em vossos pecados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 8, 25, 'Disseram-lhe pois: Quem és tu? Jesus lhes disse: [Sou] o mesmo que desde o princípio tenho vos dito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 8, 26, 'Muitas coisas tenho que dizer e julgar de vós; mas verdadeiro é aquele que me enviou; e eu, o que dele tenho ouvido, isso falo ao mundo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 8, 27, '[Mas] não entenderam que ele estava lhes falando do Pai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 8, 28, 'Jesus, então, lhes disse: Quando levantardes ao Filho do homem, então entendereis que eu sou, e que nada faço de mim mesmo; mas isto digo, como meu Pai me ensinou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 8, 29, 'E aquele que me enviou está comigo. O Pai não me tem deixado só, porque sempre faço o que lhe agrada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 8, 30, 'Falando ele estas coisas, muitos creram nele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 8, 31, 'Dizia, pois, Jesus aos judeus que criam nele: Se vós permanecerdes em minha palavra, verdadeiramente sereis meus discípulos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 8, 32, 'E conhecereis a verdade, e a verdade vos libertará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 8, 33, 'Responderam-lhe: Somos descendência de Abraão, e nunca servimos a ninguém; como, [pois] , dizes: Sereis livres?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 8, 34, 'Respondeu-lhes Jesus: Em verdade, em verdade vos digo, que todo aquele que comete pecado é servo do pecado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 8, 35, 'E o servo não fica em casa para sempre; o Filho fica para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 8, 36, 'Portanto, se o Filho vos libertar, verdadeiramente sereis livres.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 8, 37, 'Bem sei que sois descendência de Abraão; porém procurais matar-me, porque minha palavra não encontra lugar em vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 8, 38, 'Eu, o que vi junto a meu Pai, [isso] falo; e vós, o que também vistes junto a vosso pai [isso] fazeis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 8, 39, 'Responderam, e lhe disseram: Nosso pai é Abraão. Disse-lhes Jesus: Se fôsseis filhos de Abraão, faríeis as obras de Abraão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 8, 40, 'Porém agora procurais matar a mim, o homem que tenho vos falado a verdade que de Deus tenho ouvido; Abraão não fez isto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 8, 41, 'Vós fazeis as obras de vosso pai.Disseram-lhe pois: Nós não somos nascidos de pecado sexual; nós temos um Pai: Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 8, 42, 'Disse-lhes pois Jesus: Se Deus fosse vosso Pai, verdadeiramente me amaríeis; porque eu saí e venho de Deus; pois não vim de mim mesmo, porém ele me enviou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 8, 43, 'Por que não entendeis meu discurso? Porque não podeis ouvir minha palavra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 8, 44, 'Vós sois [filhos] de [vosso] pai, o Diabo, e quereis fazer os desejos de vosso pai; ele foi homicida desde o princípio, e não permaneceu na verdade, porque nele não há verdade; quando fala mentira, fala do seu próprio; porque é mentiroso, e pai da [mentira] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 8, 45, 'Porém a mim, porque [vos] digo a verdade, não credes em mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 8, 46, 'Quem de vós me convence de pecado? E se digo a verdade, por que não credes em mim?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 8, 47, 'Quem é de Deus, ouve as palavras de Deus; portanto vós não [as] ouvis porque não sois de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 8, 48, 'Responderam, pois, os Judeus, e lhe disseram: Nós não dizemos com razão que és samaritano, e tens o demônio?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 8, 49, 'Respondeu Jesus: Eu não tenho demônio, antes honro a meu Pai; e vós me desonrais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 8, 50, 'Mas eu não busco minha glória; há quem a busque, e julgue.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 8, 51, 'Em verdade, em verdade vos digo, que se alguém guardar minha palavra, jamais verá a morte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 8, 52, 'Disseram-lhe pois os Judeus: Agora conhecemos que tens o demônio. Abraão e os profetas morreram; e tu dizes: Se alguém guardar minha palavra, jamais experimentará a morte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 8, 53, 'És tu maior que nosso pai Abraão, que morreu? Os profetas também morreram. Quem tu dizes ser?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 8, 54, 'Respondeu Jesus: Se eu me glorifico a mim mesmo, minha glória é nada; meu Pai, o qual vós dizeis ser vosso Deus, ele é o que me glorifica.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 8, 55, 'E vós não o conheceis, mas eu o conheço; e se disser que não o conheço, serei mentiroso como vós; mas eu o conheço, e guardo sua palavra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 8, 56, 'Abraão, vosso pai, saltou de alegria por ver o meu dia; ele viu, e se alegrou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 8, 57, 'Disseram-lhe, pois. os Judeus: Ainda não tens cinquenta anos, e viste a Abraão?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 8, 58, 'Jesus lhes disse: Em verdade, em verdade vos digo, que antes que Abraão fosse, eu sou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 8, 59, 'Então tomaram pedras para atirarem nele. Mas Jesus se escondeu, e saiu do Templo, atravessando por meio deles, e assim se foi.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 9, 1, 'E indo [Jesus] passando, viu a um homem cego desde o nascimento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 9, 2, 'E seus discípulos lhe perguntaram, dizendo: Rabi, quem pecou? Este, ou seus pais, para que nascesse cego?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 9, 3, 'Respondeu Jesus: Nem este pecou, nem seus pais; mas sim para que as obras de Deus nele se manifestem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 9, 4, 'A mim me convém trabalhar as obras daquele que me enviou, enquanto é dia; a noite vem, quando ninguém pode trabalhar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 9, 5, 'Enquanto estiver no mundo, eu sou a luz do mundo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 9, 6, 'Dito isto, cuspiu em terra, e fez lama do cuspe, e untou com aquela lama os olhos do cego.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 9, 7, 'E disse-lhe: Vai, lava-te no tanque de Siloé (que se traduz Enviado). Foi pois, e lavou-se; e voltou vendo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 9, 8, 'Então os vizinhos, e os que de antes o viram que era cego, diziam: Não é este aquele que estava sentado, e mendigava?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 9, 9, 'Outros diziam: É este. E outros: Parece-se com ele. Ele dizia: Sou eu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 9, 10, 'Então lhe diziam: Como teus olhos se abriram?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 9, 11, 'Respondeu ele, e disse: Aquele homem chamado Jesus fez lama, untou meus olhos, e me disse: Vai ao tanque de Siloé, e lava-te. E fui, e me lavei, e vi.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 9, 12, 'Disseram-lhe, pois: Onde ele está? Disse ele: Não sei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 9, 13, 'Levaram aos Fariseus o ex-cego.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 9, 14, 'E era sábado, quando Jesus fez a lama, e abriu os olhos dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 9, 15, 'Então voltaram também os Fariseus a perguntar-lhe como vira, e ele lhes disse: Pôs lama sobre os meus olhos, e me lavei, e vejo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 9, 16, 'Então que alguns dos Fariseus diziam: Este homem não é de Deus, pois não guarda o sábado. Outros diziam: Como pode um homem pecador fazer tais sinais? E havia divisão entre eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 9, 17, 'Voltaram a dizer ao cego: Tu que dizes dele, que abriu teus olhos? E ele disse: Que é profeta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 9, 18, 'Portanto os judeus não criam nele, de que houvesse sido cego, e [passasse a] ver, até que chamaram aos pais dos que [passou a] ver.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 9, 19, 'E perguntaram-lhes, dizendo: É este vosso filho, aquele que dizeis que nasceu cego? Como pois agora vê?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 9, 20, 'Responderam-lhes seus pais, e disseram: Sabemos que este é nosso filho, e que nasceu cego;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 9, 21, 'Mas como agora ele vê, não sabemos; ou, quem lhe abriu os olhos, não sabemos; ele tem idade [suficiente] ,perguntai a ele, ele falará por si mesmo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 9, 22, 'Isto disseram seus pais, pois temiam aos judeus. Porque já os Judeus tinham combinado, que se alguém confessasse que ele era o Cristo, seria expulso da sinagoga.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 9, 23, 'Por isso disseram seus pais: Ele tem idade [suficiente] ,perguntai a ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 9, 24, 'Chamaram pois segunda vez ao homem que era cego, e disseram-lhe: Dá glória a Deus; nós sabemos que esse homem é pecador.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 9, 25, 'Respondeu pois ele, e disse: Se é pecador, não o sei; uma coisa sei, que havendo eu sido cego, agora vejo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 9, 26, 'E voltaram a lhe dizer: O que ele te fez? Como ele abriu os teus olhos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 9, 27, 'Ele lhes respondeu: Eu já vos disse, e ainda não o ouvistes; para que quereis voltar a ouvir? Por acaso vós também quereis ser discípulos dele?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 9, 28, 'Então lhe insultaram, e disseram: Tu sejas discípulo dele; mas nós somos discípulos de Moisés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 9, 29, 'Bem sabemos nós que Deus falou a Moisés; mas este nem de onde é, não sabemos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 9, 30, 'Aquele homem respondeu, e disse-lhes: Porque nisto está a maravilha: que vós não sabeis de onde ele é; e a mim abriu meus olhos!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 9, 31, 'E bem sabemos que Deus não dá ouvidos aos pecadores; mas se alguém é temente a Deus, e faz sua vontade, a este dá ouvidos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 9, 32, 'Desde o princípio dos tempos nunca se ouviu de que alguém que tenha aberto os olhos de um que tenha nascido cego.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 9, 33, 'Se este não fosse vindo de Deus, nada poderia fazer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 9, 34, 'Eles responderam, e lhe disseram: Tu és todo nascido em pecados, e nos ensina? E o lançaram fora.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 9, 35, 'Ouviu Jesus que o haviam lançado fora, e achando-o, disse-lhe: Crês tu no Filho de Deus?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 9, 36, 'Respondeu ele, e disse: Quem é, Senhor, para que nele creia?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 9, 37, 'E disse-lhe Jesus: Tu já o tens visto; e este é o que fala contigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 9, 38, 'E ele disse: Creio, Senhor; E adorou-o.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 9, 39, 'E disse Jesus: Eu vim a este mundo para juízo, para os que não veem, vejam; e os que veem, ceguem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 9, 40, 'E ouviram isto [alguns] dos fariseus, que estavam com ele; e lhe disseram: Também nós somos cegos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 9, 41, 'Disse-lhes Jesus: Se fôsseis cegos, não teríeis pecado; mas agora dizeis: Vemos; portanto vosso pecado permanece.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 10, 1, 'Em verdade, em verdade vos digo, que aquele que no curral das ovelhas não entra pela porta, mas sobe por outra parte, é ladrão, e assaltante.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 10, 2, 'Mas aquele que entra pela porta é o pastor de ovelhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 10, 3, 'A este o porteiro abre, e as ovelhas ouvem sua voz, e a suas ovelhas chama nome por nome, e as leva fora.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 10, 4, 'E quando tira fora suas ovelhas, vai adiante delas, e as ovelhas o seguem, porque conhecem sua voz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 10, 5, 'Mas ao estranho em maneira nenhuma seguirão, ao invés disso dele fugirão; porque não conhecem a voz dos estranhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 10, 6, 'Esta parábola Jesus lhes disse; porém eles não entenderam que era o que lhes falava.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 10, 7, 'Voltou pois Jesus a lhes dizer: Em verdade, em verdade vos digo, que sou a porta das ovelhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 10, 8, 'Todos quantos vieram antes de mim, são ladrões e assaltantes; mas as ovelhas não os ouviram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 10, 9, 'Eu sou a porta; se alguém entrar por mim, será salvo; e entrará, e sairá, e achará pasto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 10, 10, 'O ladrão não vem, senão para roubar, matar, e destruir; eu vim para que tenham vida, e [a] tenham em abundância.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 10, 11, 'Eu sou o bom Pastor; o bom Pastor dá sua vida pelas ovelhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 10, 12, 'Mas o contratado a dinheiro, e que não é o pastor, a quem as ovelhas não pertencem, vê o lobo vir, deixa as ovelhas, e foge; o lobo as captura, e dispersa as ovelhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 10, 13, 'E o contratado foge, porque é contratado, e não tem cuidado das ovelhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 10, 14, 'Eu sou o bom Pastor, e conheço as minhas, e pelas minhas sou conhecido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 10, 15, 'Como o Pai me conhece, assim também também eu conheço o Pai; e dou a minha vida pelas ovelhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 10, 16, 'Ainda tenho outras ovelhas que não são deste curral; a estas também me convém trazer, e ouvirão minha voz, e haverá um rebanho, [e] um pastor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 10, 17, 'Por isso o Pai me ama, porque dou a minha vida para tomá-la de volta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 43, 'João', 'Jo', 10, 18, 'Ninguém a tira de mim, mas eu de mim mesmo a dou; tenho poder para a dar, e tenho poder para tomá-la de volta. Este mandamento recebi de meu Pai.')
